// Read-only digest. Does not update the sheet and does not apply to any job.
// status must equal "draft_ready" exactly (case-sensitive), matching the scoring workflow.
// Zero matches: return no items so Gmail does not send.
const COVER_PREVIEW = 200;

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((row) => row.status === 'draft_ready');

if (rows.length === 0) {
  return [];
}

const scoreOf = (row) => {
  const n = Number(row.fitScore);
  return Number.isFinite(n) ? n : -1;
};

rows.sort((a, b) => {
  const scoreDiff = scoreOf(b) - scoreOf(a);
  if (scoreDiff !== 0) return scoreDiff;
  return String(b.receivedAt || '').localeCompare(String(a.receivedAt || ''));
});

const cell = (value) => {
  if (value === undefined || value === null || String(value).trim() === '') return '(blank)';
  return String(value).replace(/\s+/g, ' ').trim();
};

const preview = (value) => {
  const text = cell(value);
  if (text === '(blank)') return text;
  if (text.length <= COVER_PREVIEW) return text;
  return text.slice(0, COVER_PREVIEW).trimEnd() + '…';
};

const blocks = rows.map((row, index) => {
  return [
    `${index + 1}. ${cell(row.company)} — ${cell(row.title)}`,
    `   fitScore: ${cell(row.fitScore)}`,
    `   applyPriority: ${cell(row.applyPriority)}`,
    `   liveCodingRisk: ${cell(row.liveCodingRisk)}`,
    `   jobUrl: ${cell(row.jobUrl)}`,
    `   receivedAt: ${cell(row.receivedAt)}`,
    `   coverLetter: ${preview(row.coverLetter)}`,
  ].join('\n');
});

const checkedAt = $now.setZone('America/Winnipeg').toFormat('yyyy-LL-dd HH:mm');

const body = [
  `Open drafts waiting: ${rows.length}`,
  `Checked: ${checkedAt} America/Winnipeg`,
  'Review in Google Sheets. This digest does not apply to any job.',
  '',
  blocks.join('\n\n'),
].join('\n');

return [
  {
    json: {
      count: rows.length,
      subject: `Draft digest: ${rows.length} open`,
      body,
    },
  },
];
